{
  "ruleset_id": "additional-education-programme",
  "rules": [
    {
      "description": "The organization must have a valid education license.",
      "severity": "critical",
      "category": "licensing",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The programme duration must be at least 72 hours.",
      "severity": "critical",
      "category": "curriculum",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "At least 80% of teachers must have relevant qualification.",
      "severity": "critical",
      "category": "staffing",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "The delivery format may be only in-person or blended.",
      "severity": "critical",
      "category": "delivery",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "subsidy-energy-efficiency",
  "rules": [
    {
      "description": "Project must reduce energy consumption by at least 20%.",
      "severity": "critical",
      "category": "energy_efficiency",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Applicant co-financing share must be at least 30%.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "A technical passport for the facility must be attached to the application.",
      "severity": "critical",
      "category": "document",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Works must be completed no later than 2027-12-31.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "socialnyy-kontrakt",
  "rules": [
    {
      "description": "Applicant household must be in Moscow or Moscow Oblast.",
      "severity": "critical",
      "category": "region",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": ["Москва", "Московская область"]
      }
    },
    {
      "description": "Household monthly income per person must not exceed 25,000 RUB.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Consent for personal data processing is required.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Applicant must have employment status unemployed or job_seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": ["unemployed", "job_seeker"]
      }
    }
  ]
}
